import {
  AfterViewInit,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  ContentChildren,
  DOCUMENT,
  DoCheck,
  ElementRef,
  HostBinding,
  Injector,
  Input,
  OnChanges,
  OnInit,
  QueryList,
  SimpleChanges,
  ViewChild,
  forwardRef,
  inject,
} from '@angular/core';
import {
  ControlValueAccessor,
  FormGroupDirective,
  NG_VALUE_ACCESSOR,
  NgControl,
  NgForm,
} from '@angular/forms';
import {
  QDestroyService,
  QSharedResizeObserverService,
} from '@questrade/allspark-angular-components/core/services';
import { ErrorState, voidFn } from '@questrade/allspark-angular-components/core/utils';
import {
  ErrorStateMatcher,
  ErrorStateMatcherInterface,
  FormFieldControl,
} from '@questrade/allspark-angular-components/form-control';
import { takeUntil } from 'rxjs';
import { QToggleButtonComponent } from '../toggle-button.component';
import { QToggleButtonGroupVariant } from '../types/toggle-button-group-variant.type';
import { Q_TOGGLE_BUTTON_GROUP } from '../types/toggle-button-group.const';
import { QToggleButtonGroup } from '../types/toggle-button-group.interface';

let nextUniqueId = 0;

@Component({
  selector: 'q-toggle-button-group',
  templateUrl: './toggle-button-group.component.html',
  styleUrls: ['./toggle-button-group.component.scss'],
  providers: [
    { provide: Q_TOGGLE_BUTTON_GROUP, useExisting: QToggleButtonGroupComponent },
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => QToggleButtonGroupComponent),
      multi: true,
    },
    { provide: FormFieldControl, useExisting: QToggleButtonGroupComponent },
    QDestroyService,
  ],
  host: { '[attr.id]': 'controlId' },
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class QToggleButtonGroupComponent<T>
  extends ErrorState
  implements
    ControlValueAccessor,
    FormFieldControl,
    DoCheck,
    OnInit,
    OnChanges,
    AfterViewInit,
    QToggleButtonGroup<T>
{
  @Input() controlId = `q-toggle-button-group-${nextUniqueId++}`;
  @Input() widthStrategy: 'auto' | '100%' = 'auto';
  @Input() override errorStateMatcher: ErrorStateMatcherInterface = new ErrorStateMatcher();
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-toggle-button-group';

  @Input() set type(value: QToggleButtonGroupVariant) {
    this._type = value;
    this.markButtonsForCheck();
  }
  get type(): QToggleButtonGroupVariant {
    return this._type;
  }

  @Input() set value(value: T | null) {
    this._value = value;
    this.markButtonsForCheck();
    this._controlValueAccessorChangeFn(value);

    this.setIndicatorPosition();
  }
  get value(): T | null {
    return this._value;
  }

  @Input() get disabled(): boolean {
    return this._disabled;
  }
  set disabled(value: boolean) {
    this._disabled = value;
    this.markButtonsForCheck();
  }

  @ContentChildren(forwardRef(() => QToggleButtonComponent), { descendants: true })
  private _buttons!: QueryList<QToggleButtonComponent<T>>;

  @ViewChild('indicator') _indicatorRef!: ElementRef<HTMLElement>;

  _selectedElementIndex: number | null = null;
  _onTouched: () => void = voidFn;
  _controlValueAccessorChangeFn: (value: T | null) => void = voidFn;

  private _type: QToggleButtonGroupVariant = 'standard';
  private _value: T | null = null;
  private _disabled = false;
  private readonly _sharedResizeObserverService = inject(QSharedResizeObserverService);
  private readonly _document = inject(DOCUMENT);
  private readonly _destroy$ = inject(QDestroyService);
  private readonly _elementRef = inject(ElementRef);
  private readonly _changeDetector = inject(ChangeDetectorRef);
  private readonly injector = inject<Injector>(Injector);

  constructor() {
    super(inject(FormGroupDirective, { optional: true }), inject(NgForm, { optional: true }));
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes.widthStrategy?.currentValue && !changes.widthStrategy?.isFirstChange()) {
      this.markButtonsForCheck();

      setTimeout(() => {
        this.setIndicatorPosition();
      });
    }
  }

  ngOnInit(): void {
    this.setComponentControl();
  }

  ngAfterViewInit(): void {
    this._sharedResizeObserverService
      .observe(this._document.body)
      ?.pipe(takeUntil(this._destroy$))
      .subscribe(() => {
        if (this.widthStrategy === '100%') {
          this.setIndicatorPosition();
        }
      });
    this.setIndicatorPosition();
  }

  ngDoCheck(): void {
    if (this.ngControl) {
      this._updateErrorState();
    }
  }

  /** @hidden */
  writeValue(value: T): void {
    this.value = value;
  }

  /** @hidden */
  registerOnChange(fn: (value: T | null) => void): void {
    this._controlValueAccessorChangeFn = fn;
  }

  /** @hidden */
  registerOnTouched(fn: () => void): void {
    this._onTouched = fn;
  }

  /** @hidden */
  setDisabledState(isDisabled: boolean): void {
    this.disabled = isDisabled;
  }

  /** @hidden */
  markButtonsForCheck(): void {
    this._buttons?.forEach((button) => button._markForCheck());
  }

  get selectedElementWidth(): number | null {
    if (this.selectedElement) {
      return this.selectedElement.nativeElement.clientWidth as number;
    }

    return null;
  }

  get selectedElement(): ElementRef<HTMLButtonElement> | null {
    for (let i = 0; i < this._buttons.length; i++) {
      const button = this._buttons.get(i);

      if (button?.selected) {
        this._selectedElementIndex = i;

        return button._elementRef;
      }
    }

    return null;
  }

  get indicatorLeftPosition(): number | null {
    if (this.selectedElement) {
      const selectedElementLeft = this.selectedElement.nativeElement.getBoundingClientRect().left;
      const formGroupLeft = this._elementRef.nativeElement.getBoundingClientRect().left;
      const borderWidth = 1;

      return selectedElementLeft - formGroupLeft - borderWidth;
    }

    return null;
  }

  private setComponentControl(): void {
    const injectedControl = this.injector.get(NgControl, null);

    if (injectedControl) {
      this.ngControl = injectedControl;
    }
  }

  private setIndicatorPosition(): void {
    if (this._indicatorRef) {
      const leftPosition = this.indicatorLeftPosition;
      const selectedElementWidth = this.selectedElementWidth;

      if (leftPosition !== null && selectedElementWidth !== null) {
        this._indicatorRef.nativeElement.style.left = `${leftPosition}px`;
        this._indicatorRef.nativeElement.style.width = `${selectedElementWidth}px`;
        this._indicatorRef.nativeElement.style.visibility = 'visible';
      } else {
        this._indicatorRef.nativeElement.style.visibility = 'hidden';
      }

      this._changeDetector.markForCheck();
    }
  }
}
