import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  ElementRef,
  HostBinding,
  Input,
  ViewEncapsulation,
  inject,
} from '@angular/core';
import { QToggleButtonGroupVariant } from './types/toggle-button-group-variant.type';
import { Q_TOGGLE_BUTTON_GROUP } from './types/toggle-button-group.const';
import { QToggleButtonGroup } from './types/toggle-button-group.interface';

@Component({
  selector: 'q-toggle-button',
  templateUrl: './toggle-button.component.html',
  styleUrls: ['./toggle-button.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
})
export class QToggleButtonComponent<T> {
  @Input() value: T | null = null;
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-toggle-button';

  @Input() get disabled(): boolean {
    return this._disabled || !!this.toggleButtonGroup?.disabled;
  }
  set disabled(value: boolean) {
    this._disabled = value;
  }

  @Input() set type(value: QToggleButtonGroupVariant) {
    this._type = value;
  }
  get type(): QToggleButtonGroupVariant {
    return this.toggleButtonGroup?.type || this._type;
  }

  @Input() get selected(): boolean {
    return (
      this._selected || (!!this.toggleButtonGroup && this.toggleButtonGroup.value === this.value)
    );
  }

  set selected(value: boolean) {
    if (this.toggleButtonGroup) {
      if (value) {
        this.toggleButtonGroup.value = this.value;
      } else if (!value && this.toggleButtonGroup.value === this.value) {
        this.toggleButtonGroup.value = null;
        this.toggleButtonGroup = null;
      }
    } else {
      this._selected = value;
      this._markForCheck();
    }
  }

  // TODO: revisit it when migrated to viewEncapsulation.none (can be done on parent via css).
  @HostBinding('style.width') get widthStyle(): string {
    return this.width === '100%' ? 'inherit' : '';
  }

  toggleButtonGroup = inject<QToggleButtonGroup<T> | null>(Q_TOGGLE_BUTTON_GROUP, {
    optional: true,
  });
  readonly _elementRef = inject(ElementRef);

  private _selected = false;
  private _disabled = false;
  private _type: QToggleButtonGroupVariant = 'standard';
  private readonly _changeDetector = inject(ChangeDetectorRef);

  onButtonClick(event: Event): void {
    event.preventDefault();
    event.stopPropagation();

    if (this.disabled) return;

    this.selected = true;

    this.toggleButtonGroup?._onTouched();
  }

  _markForCheck(): void {
    this._changeDetector.markForCheck();
  }

  get standalone(): boolean {
    return this.toggleButtonGroup === null;
  }

  get width(): string {
    return this.toggleButtonGroup?.widthStrategy ?? 'auto';
  }
}
